#!/usr/bin/env python3
"""Brute-force decode the Photon v6 Protocol18 GetRegions response frame."""
HEX = ("f303dc00000802d2471102657502757303757377036361650461736961026a7002617502736102696e02727503727565026b72027a6102747203756165047573736302686b"
       "")
B = bytes.fromhex(HEX)

def vint(d, o):
    r = 0; s = 0
    while True:
        b = d[o]; o += 1
        r |= (b & 0x7F) << s
        if not (b & 0x80): return r, o
        s += 7

# region name set for scoring
regions = ["eu","us","usw","cae","asia","jp","au","sa","in","ru","rue","kr","za","tr","uae","ussc","hk"]

def try_string(d, o):
    """type byte already consumed. try [varint len][utf8]"""
    try:
        n, o2 = vint(d, o)
        s = d[o2:o2+n].decode()
        return s, o2 + n
    except Exception:
        return None, o

def scan(d, o, out):
    """walk: expect [len][str] repeated until buffer end or urls start"""
    got = []
    while o < len(d):
        s, o2 = try_string(d, o)
        if s is None: break
        got.append(s)
        o = o2
    return got, o

# hypothesis: params section starts at some offset; find 'eu' region list
for start in range(3, 16):
    o = start
    names, o2 = scan(B, o, [])
    if len(names) >= 15 and all(r in names for r in ["eu","asia","hk"]):
        print(f"OFFSET {start}: names({len(names)}) = {names}")
        print(f"  after names, first 80 bytes: {B[o2:o2+80].hex()}")
        # try urls
        urls, o3 = scan(B, o2, [])
        print(f"  urls({len(urls)}): {[u[:36] for u in urls[:3]]} ...")
        if len(urls) == len(names):
            print("  NAMES/URLS MATCH → decoded!")
            # remaining bytes?
            print(f"  tail: {B[o3:].hex()}")
        break
